const REPORT_LOGO_BASE64 = "";

const FEES = [
  { key: "acquisition", label: "Acquisition Fee", annual: false },
  { key: "loanGuarantee", label: "Loan Guarantee Fees", annual: false },
  { key: "loanRefinance", label: "Loan Refinance Fee", annual: false },
  { key: "assetManagement", label: "Annual Asset Management Fee", annual: true }
];

const feesBody = document.getElementById("feesBody");

function numeric(value) {
  const parsed = Number(String(value).replace(/,/g, ""));
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
}

function formatNumericInput(input) {
  const digits = input.value.replace(/\D/g, "");
  input.value = digits ? Number(digits).toLocaleString("en-US") : "";
}

function money(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(Number.isFinite(value) ? value : 0);
}

function renderFees() {
  feesBody.innerHTML = FEES.map((fee) => `
    <tr data-fee="${fee.key}">
      <th scope="row">${fee.label}</th>
      <td class="input-cell">
        <span class="currency-prefix">$</span>
        <input data-field="amount" type="text" value="0" inputmode="numeric" data-numeric aria-label="${fee.label} amount" />
      </td>
      ${fee.annual ? `
        <td class="input-cell years-input">
          <input data-field="years" type="text" value="0" inputmode="numeric" data-numeric aria-label="Number of years in project" />
        </td>
      ` : '<td class="not-applicable" aria-label="Not applicable">—</td>'}
      <td class="calculated" data-output="total">$0</td>
    </tr>
  `).join("");
}

function calculate() {
  const rows = [...feesBody.querySelectorAll("tr")];
  const fees = rows.map((row, index) => {
    const amount = numeric(row.querySelector('[data-field="amount"]').value);
    const yearsInput = row.querySelector('[data-field="years"]');
    const years = yearsInput ? numeric(yearsInput.value) : 1;
    const total = amount * years;
    row.querySelector('[data-output="total"]').textContent = money(total);
    return { ...FEES[index], amount, years, total };
  });

  const oneTimeTotal = fees.filter((fee) => !fee.annual).reduce((sum, fee) => sum + fee.total, 0);
  const annualTotal = fees.filter((fee) => fee.annual).reduce((sum, fee) => sum + fee.total, 0);
  const totalFees = oneTimeTotal + annualTotal;

  document.getElementById("totalFees").textContent = money(totalFees);
  document.getElementById("summaryOneTime").textContent = money(oneTimeTotal);
  document.getElementById("summaryAnnual").textContent = money(annualTotal);
  document.getElementById("summaryTotal").textContent = money(totalFees);

  return { fees, oneTimeTotal, annualTotal, totalFees };
}

function pdfEscape(value) {
  return String(value).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)").replace(/[^\x20-\x7e]/g, "-");
}

function pdfText(value, x, y, size = 9, font = "F1") {
  return `BT /${font} ${size} Tf ${x} ${y} Td (${pdfEscape(value)}) Tj ET\n`;
}

async function createPdf() {
  const data = calculate();
  const name = document.getElementById("fullName").value.trim() || "Not provided";
  const email = document.getElementById("email").value.trim() || "Not provided";
  const logoBinary = atob(REPORT_LOGO_BASE64);
  const logoBytes = Uint8Array.from(logoBinary, (character) => character.charCodeAt(0));
  const width = 612;
  const height = 792;
  const left = 42;
  const tableWidth = 528;
  const rowHeight = 29;
  const tableTop = 594;
  const columnWidths = [190, 116, 98, 124];
  const headers = ["FEE", "FEE AMOUNT", "# YEARS", "TOTAL FEE"];
  let stream = "";

  if (logoBytes) stream += "q 90 0 0 83.7 480 678 cm /Logo Do Q\n";
  stream += "0.06 0.09 0.16 rg\n" + pdfText("DISCLOSURE OF FEES", left, 744, 22, "F2");
  stream += "0.39 0.45 0.55 rg\n" + pdfText(`Prepared for: ${name}`, left, 720, 9) + pdfText(`Email: ${email}`, left, 706, 9);
  stream += pdfText(`Generated: ${new Date().toLocaleDateString("en-US")}`, left, 692, 9);
  stream += "0.06 0.09 0.16 rg\n" + pdfText("FEE ANALYSIS", left, 638, 13, "F2");

  stream += `0.95 0.96 0.98 rg\n${left} ${tableTop} ${tableWidth} ${rowHeight} re f\n`;
  stream += "0.80 0.84 0.88 RG 0.6 w\n";
  const rowCount = data.fees.length + 2;
  for (let i = 0; i <= rowCount; i += 1) {
    const y = tableTop + rowHeight - i * rowHeight;
    stream += `${left} ${y} m ${left + tableWidth} ${y} l S\n`;
  }
  let x = left;
  stream += `${left} ${tableTop + rowHeight} m ${left} ${tableTop + rowHeight - rowCount * rowHeight} l S\n`;
  columnWidths.forEach((columnWidth) => {
    x += columnWidth;
    stream += `${x} ${tableTop + rowHeight} m ${x} ${tableTop + rowHeight - rowCount * rowHeight} l S\n`;
  });

  x = left;
  stream += "0.06 0.09 0.16 rg\n";
  headers.forEach((header, index) => {
    stream += pdfText(header, x + 5, tableTop + 10, 8, "F2");
    x += columnWidths[index];
  });

  data.fees.forEach((fee, index) => {
    const y = tableTop - 19 - index * rowHeight;
    const values = [fee.label, money(fee.amount), fee.annual ? fee.years.toLocaleString("en-US") : "-", money(fee.total)];
    x = left;
    values.forEach((value, cell) => {
      stream += pdfText(value, x + 5, y, cell === 0 ? 8.4 : 8.2, cell === 0 ? "F2" : "F1");
      x += columnWidths[cell];
    });
  });

  const totalY = tableTop - 19 - data.fees.length * rowHeight;
  stream += pdfText("TOTAL FEE TO GENERAL PARTNERS", left + 5, totalY, 8.6, "F2");
  stream += pdfText(money(data.totalFees), left + columnWidths[0] + columnWidths[1] + columnWidths[2] + 5, totalY, 8.6, "F2");

  const summaryTop = 355;
  stream += "0.96 0.98 0.95 rg\n42 289 528 66 re f\n";
  stream += "0.77 0.85 0.75 RG 0.7 w\n42 289 528 66 re S\n";
  stream += "0.22 0.36 0.24 rg\n" + pdfText("TOTAL FEE TO GENERAL PARTNERS", 56, summaryTop - 24, 10, "F2");
  stream += pdfText(money(data.totalFees), 426, summaryTop - 26, 15, "F2");
  stream += "0.39 0.45 0.55 rg\n" + pdfText("One-time fees plus the annual asset management fee over the project term.", 56, summaryTop - 45, 8);

  const encoder = new TextEncoder();
  const objects = [];
  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";
  objects[2] = "<< /Type /Pages /Kids [3 0 R] /Count 1 >>";
  const logoResource = logoBytes ? " /XObject << /Logo 7 0 R >>" : "";
  objects[3] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${width} ${height}] /Resources << /Font << /F1 5 0 R /F2 6 0 R >>${logoResource} >> /Contents 4 0 R >>`;
  objects[4] = `<< /Length ${encoder.encode(stream).length} >>\nstream\n${stream}endstream`;
  objects[5] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";
  objects[6] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>";
  if (logoBytes) objects[7] = logoBytes;

  const chunks = [];
  let byteLength = 0;
  const appendText = (value) => {
    const bytes = encoder.encode(value);
    chunks.push(bytes);
    byteLength += bytes.length;
  };
  const appendBytes = (bytes) => {
    chunks.push(bytes);
    byteLength += bytes.length;
  };

  appendText("%PDF-1.4\n");
  const offsets = [0];
  for (let i = 1; i < objects.length; i += 1) {
    offsets[i] = byteLength;
    appendText(`${i} 0 obj\n`);
    if (i === 7 && logoBytes) {
      appendText(`<< /Type /XObject /Subtype /Image /Width 371 /Height 345 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logoBytes.length} >>\nstream\n`);
      appendBytes(logoBytes);
      appendText("\nendstream");
    } else {
      appendText(objects[i]);
    }
    appendText("\nendobj\n");
  }
  const xref = byteLength;
  appendText(`xref\n0 ${objects.length}\n0000000000 65535 f \n`);
  for (let i = 1; i < objects.length; i += 1) appendText(`${String(offsets[i]).padStart(10, "0")} 00000 n \n`);
  appendText(`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);
  return new Blob(chunks, { type: "application/pdf" });
}

async function downloadPdf() {
  const button = document.getElementById("downloadPdf");
  const status = document.getElementById("downloadStatus");
  button.disabled = true;
  status.textContent = "Preparing PDF...";
  try {
    const url = URL.createObjectURL(await createPdf());
    const link = document.createElement("a");
    const fileName = (document.getElementById("fullName").value.trim() || "analysis")
      .replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase();
    link.href = url;
    link.download = `disclosure-of-fees-${fileName}.pdf`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    status.textContent = "PDF downloaded.";
    setTimeout(() => { status.textContent = ""; }, 3000);
  } catch (error) {
    console.error("PDF generation failed.", error);
    status.textContent = "PDF could not be generated. Please try again.";
  } finally {
    button.disabled = false;
  }
}

function handleFocus(event) {
  if (event.target.matches("[data-numeric]") && numeric(event.target.value) === 0) event.target.value = "";
}

function handleBlur(event) {
  if (event.target.matches("[data-numeric]") && event.target.value.trim() === "") {
    event.target.value = "0";
    calculate();
  }
}

renderFees();
document.addEventListener("input", (event) => {
  if (event.target.matches("[data-numeric]")) {
    formatNumericInput(event.target);
    calculate();
  }
});
document.addEventListener("focusin", handleFocus);
document.addEventListener("focusout", handleBlur);
document.getElementById("downloadPdf").addEventListener("click", downloadPdf);
calculate();
